"""D2.4H — goal-conditioned path experiments generated by a small grammar.

The next tests are derived from filesystem structure + a general root-boundary
safety predicate; no historical bug names or patch diffs enter this generator.

This is NOT exhaustive fuzzing, a complete symbolic executor, or a claim that
passing the generated tests proves security.
"""
from __future__ import annotations

from dataclasses import asdict, dataclass
from hashlib import sha256
import json
import os
from pathlib import Path
from tempfile import TemporaryDirectory
from time import perf_counter
from types import SimpleNamespace

from scripts.d24f_starlette_real_regression import source_lookup_callable


@dataclass(frozen=True)
class GeneratedPath:
    family: str
    relative_input: str
    level: int
    rationale: str


def program_independent_path_grammar(root: str) -> tuple[GeneratedPath, ...]:
    if not root.isidentifier():
        raise ValueError("root must be a simple local folder token")
    return (
        GeneratedPath("benign", "index.html", 0, "existing in-scope file"),
        GeneratedPath("benign", "images/icon.svg", 0, "nested in-scope file"),
        GeneratedPath("benign", "images/../index.html", 0, "normalized in-scope file"),
        GeneratedPath("benign", "missing.txt", 0, "nonexistent file"),
        GeneratedPath("parent_boundary", "../outside.txt", 0, "generic parent traversal"),
        GeneratedPath("parent_boundary", "images/../../outside.txt", 1, "composed traversal"),
        GeneratedPath("name_relation", f"../{root}2.txt", 1, "sibling with related basename"),
        GeneratedPath("name_relation", f"../{root}_private/secret.txt", 1, "sibling name extension"),
        GeneratedPath("name_relation", f"../{root}-backup/log.txt", 1, "sibling name alternative"),
        GeneratedPath("symlink", "escape.link", 1, "in-tree symbolic link to sibling"),
        GeneratedPath("symlink", "inside.link", 1, "in-tree symbolic link to inside"),
        GeneratedPath("normalized", "./images/icon.svg", 1, "dot segment normalization"),
        GeneratedPath("normalized", "images/./icon.svg", 1, "nested dot segment"),
        GeneratedPath("normalized", "images/../images/icon.svg", 2, "equivalent path rewrite"),
    )


def run_generated_path_exploration(source: Path, *, max_probes: int = 32) -> dict:
    """Run genuine upstream StaticFiles.lookup_path in a temporary filesystem."""
    if type(max_probes) is not int or not 1 <= max_probes <= 512:
        raise ValueError("explicit safe experimental budget required")
    clock = perf_counter()
    fn, source_sha = source_lookup_callable(source)
    with TemporaryDirectory(prefix="scm-path-grammar-") as tmp:
        base = Path(tmp)
        root = base / "public"
        (root/"images").mkdir(parents=True)
        (root/"index.html").write_text("public\n")
        (root/"images/icon.svg").write_text("public icon\n")
        (base/"outside.txt").write_text("dummy local fixture\n")
        (base/"public2.txt").write_text("dummy sibling\n")
        (base/"public_private").mkdir()
        (base/"public_private/secret.txt").write_text("dummy sibling\n")
        (base/"public-backup").mkdir()
        (base/"public-backup/log.txt").write_text("dummy sibling\n")
        try:
            (root/"escape.link").symlink_to(base/"outside.txt")
            (root/"inside.link").symlink_to(root/"index.html")
        except (OSError, NotImplementedError):
            # Do not silently report failure as safety.
            raise RuntimeError("symlink support required for this exploration")
        receiver=SimpleNamespace(all_directories=[str(root)],follow_symlink=False)
        root_real=os.path.realpath(root)
        grammar=program_independent_path_grammar(root.name)
        results=[]
        budget_used=0
        deferred=[]
        for probe in grammar:
            if budget_used >= max_probes:
                deferred.append(probe.relative_input)
                continue
            target_path = os.path.realpath(os.path.join(root,probe.relative_input))
            exists = os.path.isfile(target_path)
            expected = ("DENY" if not exists or
                        os.path.commonpath((root_real,target_path)) != root_real
                        else "ALLOW")
            actual_path, stat = fn(receiver, probe.relative_input)
            observed = "ALLOW" if stat is not None else "DENY"
            if observed=="ALLOW":
                if not os.path.isfile(actual_path):
                    raise RuntimeError("program claimed nonexistent file")
                actual_real = os.path.realpath(actual_path)
                if actual_real!=target_path:
                    raise RuntimeError("program and oracle resolved different target files")
            item={
                **asdict(probe),"expected":expected,"observed":observed,
                "violates_independent_boundary":observed!=expected,
                "underlying_file_exists":exists,
                "actual_relative_target":os.path.relpath(target_path,base),
            }
            results.append(item)
            budget_used+=1
        hits=[r for r in results if r["violates_independent_boundary"]]
        hits.sort(key=lambda r:(len(r["relative_input"]),r["relative_input"]))
        report={
            "schema":"scm.prism.d24h.path-grammar.v1",
            "source_sha256":source_sha,
            "strategy":"FUNCTIONAL_METAMORPHIC_PATH_GRAMMAR",
            "budget":{"max_probes":max_probes,"used_probes":budget_used},
            "candidates_proposed":len(grammar),
            "unexecuted_candidates":deferred,
            "status":("LOCAL_PROPERTY_WITNESS" if hits else
                      "INCOMPLETE_UNKNOWN" if deferred else "NO_WITNESS_NOT_SAFE"),
            "violations":hits,
            "minimal_observed_witness":hits[0] if hits else None,
            "observations":results,
            "replay_sha256":sha256(json.dumps(results,sort_keys=True).encode()).hexdigest(),
            "elapsed_seconds":perf_counter()-clock,
            "not_exhaustive":True,
            "new_unknown_vulnerability_confirmed":False,
        }
    return report
